// Junta os resultados de todas as consultas (Prometheus + Loki) num só
// objeto e monta o relatório executivo em HTML (depois convertido pra PDF
// pelo node Gotenberg). Todas as consultas rodam em CADEIA (uma depois da
// outra), não em paralelo -- é o que garante que este node só executa UMA
// vez, com todos os dados já prontos.
function firstValue(nodeName) {
  try {
    const result = $(nodeName).first().json.data.result;
    if (!result || !result.length) return null;
    return parseFloat(result[0].value[1]);
  } catch (e) {
    return null;
  }
}

function topEndpoints(nodeName) {
  try {
    const result = $(nodeName).first().json.data.result;
    if (!result || !result.length) return [];
    return result
      .map(r => ({ view: r.metric.view || '(sem nome)', count: parseFloat(r.value[1]) }))
      .sort((a, b) => b.count - a.count);
  } catch (e) {
    return [];
  }
}

// Nomes técnicos de endpoint viram rótulos legíveis pro cliente
// não-técnico. Lista pequena e explícita -- crescer conforme necessário,
// não vale a pena tentar "adivinhar" isso genericamente.
const FRIENDLY_NAMES = {
  'product-list': 'Catálogo de produtos',
  'product-summary': 'Resumo de produtos',
  'product-total': 'Totais de produtos',
  'public-publications-list': 'Lista de publicações',
  'public-publications-detail': 'Detalhe de publicação',
  'publications-aggregate': 'Indicadores de publicações',
  'policy-proposal-list': 'Propostas de política',
};
const friendlyName = (view) => FRIENDLY_NAMES[view] || view;

const cfg = $('Configuração').first().json;

const uptime = firstValue('Uptime');
const totalRequests = firstValue('Requisições totais');
const totalErrors = firstValue('Erros 5xx totais');
const p95 = firstValue('Latência p95 média');
const errorLogLines = firstValue('Linhas de log de erro');
const topEnds = topEndpoints('Top 3 endpoints');

const fmtInt = (v) => (v === null || Number.isNaN(v)) ? '—' : Math.round(v).toLocaleString('pt-BR');
const fmtPct = (v) => (v === null || Number.isNaN(v)) ? '—' : v.toFixed(2).replace('.', ',') + '%';
const fmtMs = (v) => (v === null || Number.isNaN(v)) ? '—' : Math.round(v * 1000).toLocaleString('pt-BR') + ' ms';

const errorRate = (totalRequests && totalErrors !== null && totalRequests > 0)
  ? (totalErrors / totalRequests) * 100
  : 0;

const now = new Date();
const firstDay = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDay = new Date(now.getFullYear(), now.getMonth(), 0);
const monthName = firstDay.toLocaleDateString('pt-BR', { month: 'long' });
const monthLabel = `${monthName} de ${firstDay.getFullYear()}`;
const monthLabelCap = monthLabel.charAt(0).toUpperCase() + monthLabel.slice(1);
const periodLabel = `${firstDay.getDate()} a ${lastDay.getDate()} de ${monthName} de ${firstDay.getFullYear()}`;

const accent = cfg.client_primary_color || '#0EA5E9';
const uptimeOk = uptime === null || uptime >= 99.5;
const errorsOk = errorRate < 1;
const allGood = uptimeOk && errorsOk;

// --- Resumo executivo humanizado (não é um parágrafo robótico de template) ---
let openingLine;
if (allGood) {
  openingLine = `${monthNameCapFirst(monthName)} foi um mês tranquilo pra plataforma da ${cfg.client_name}.`;
} else if (!uptimeOk && errorsOk) {
  openingLine = `${monthNameCapFirst(monthName)} teve uma ou mais interrupções que vale a pena olhar com atenção.`;
} else if (uptimeOk && !errorsOk) {
  openingLine = `${monthNameCapFirst(monthName)} ficou no ar o tempo todo, mas registrou mais erros do que o esperado.`;
} else {
  openingLine = `${monthNameCapFirst(monthName)} teve alguns percalços que merecem atenção da equipe técnica.`;
}
function monthNameCapFirst(m) { return m.charAt(0).toUpperCase() + m.slice(1); }

const volumeLine = totalRequests
  ? `A aplicação respondeu a <strong>${fmtInt(totalRequests)} solicitações</strong> ao longo do mês${uptimeOk ? ', sem uma única interrupção registrada' : ''}.`
  : `Não foi possível medir o volume de uso neste período.`;

const topLine = topEnds.length
  ? `O recurso mais procurado pelos usuários foi <strong>${friendlyName(topEnds[0].view)}</strong>, com ${fmtInt(topEnds[0].count)} acessos no período.`
  : '';

const closingLine = allGood
  ? `Nenhuma ação é necessária da parte de vocês — está tudo funcionando como esperado.`
  : `Nossa equipe já está de olho nisso; qualquer novidade, avisamos antes mesmo deste relatório.`;

const summaryHtml = `${openingLine} ${volumeLine} ${topLine} ${closingLine}`;

// --- Gráfico de barras (SVG) dos recursos mais usados, sem infra/monitoramento ---
const maxCount = topEnds.length ? Math.max(...topEnds.map(e => e.count)) : 1;
const barRows = topEnds.length
  ? topEnds.map((e) => {
      const pct = Math.max(4, Math.round((e.count / maxCount) * 100));
      return `
      <div style="margin-bottom:9px;">
        <div style="display:flex;justify-content:space-between;font-size:12.5px;color:var(--ink);margin-bottom:4px;">
          <span style="font-weight:600;">${friendlyName(e.view)}</span>
          <span style="color:var(--muted);font-variant-numeric:tabular-nums;">${fmtInt(e.count)}</span>
        </div>
        <div style="background:var(--line);border-radius:5px;height:9px;overflow:hidden;">
          <div style="width:${pct}%;height:100%;background:var(--accent);border-radius:5px;"></div>
        </div>
      </div>`;
    }).join('')
  : `<p style="color:var(--muted);font-size:13px;">Ainda não há uso suficiente pra destacar um recurso específico este mês.</p>`;

// --- Ícones inline (monocromáticos, herdam a cor via currentColor) ---
const ICONS = {
  uptime: '<path d="M3 12h4l2-7 4 14 2-7h6" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
  volume: '<path d="M4 20V10M10 20V4M16 20v-7M22 20v-3" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round"/>',
  errors: '<path d="M12 3l8 4v5c0 5-3.4 8.4-8 9.5C7.4 20.4 4 17 4 12V7l8-4z" stroke="currentColor" stroke-width="1.7" fill="none" stroke-linejoin="round"/><path d="M9 12l2 2 4-4.5" stroke="currentColor" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
  speed: '<circle cx="12" cy="13" r="8" stroke="currentColor" stroke-width="1.7" fill="none"/><path d="M12 13l4-4M12 6v1.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>',
};
const icon = (name) => `<svg width="18" height="18" viewBox="0 0 24 24">${ICONS[name]}</svg>`;

const html = `<!doctype html>
<html lang="pt-br">
<head>
<meta charset="utf-8">
<style>
  :root {
    --ink: #172420;
    --paper: #F7F5EE;
    --paper-raised: #FFFFFF;
    --line: #E1DDCE;
    --muted: #6E7568;
    --accent: ${accent};
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; background: var(--paper); color: var(--ink);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
    font-size: 14px; line-height: 1.65;
  }
  .serif { font-family: ui-serif, Georgia, 'Iowan Old Style', 'Palatino Linotype', serif; }
  .mono { font-family: ui-monospace, 'SF Mono', 'Cascadia Code', 'Roboto Mono', Menlo, Consolas, monospace; }
  .page { max-width: 760px; margin: 0 auto; }
  .hero {
    padding: 22px 48px 16px;
    background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 10%, var(--paper)) 0%, var(--paper) 100%);
    border-bottom: 1px solid var(--line);
  }
  .hero-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 28px; }
  .hero-top img { height: 34px; width: auto; }
  .eyebrow { font-size: 11px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent); }
  .hero h1 { font-size: 30px; font-weight: 500; margin: 6px 0 4px; letter-spacing: -0.01em; }
  .hero .period { color: var(--muted); font-size: 13px; }
  .content { padding: 16px 48px 8px; }
  .pullquote {
    font-family: ui-serif, Georgia, 'Iowan Old Style', 'Palatino Linotype', serif;
    font-style: italic; font-size: 16.5px; line-height: 1.5; color: var(--ink);
    padding-left: 18px; border-left: 3px solid var(--accent); margin: 0 0 16px;
  }
  .pullquote strong { font-style: normal; font-weight: 600; }
  .kpi-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 18px; }
  .kpi {
    background: var(--paper-raised); border: 1px solid var(--line); border-radius: 10px;
    padding: 13px 13px;
  }
  .kpi .icon { color: var(--accent); margin-bottom: 10px; }
  .kpi .label { font-size: 10.5px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted); }
  .kpi .value { font-family: ui-serif, Georgia, serif; font-size: 24px; font-weight: 600; margin: 5px 0 2px; }
  .kpi .status { font-size: 10.5px; font-weight: 600; }
  .kpi .status.ok { color: #2f7a4f; }
  .kpi .status.warn { color: #b8790a; }
  .section-title { font-family: ui-serif, Georgia, serif; font-size: 15.5px; font-weight: 600; margin: 0 0 3px; }
  .section-sub { font-size: 12px; color: var(--muted); margin-bottom: 12px; }
  .divider { height: 1px; background: var(--line); margin: 14px 0; }
  .footer {
    padding: 10px 48px 16px; display: flex; justify-content: space-between;
    align-items: center; font-size: 11px; color: var(--muted);
  }
  .footer .brand { font-weight: 600; color: var(--ink); }
</style>
</head>
<body>
<div class="page">

  <div class="hero">
    <div class="hero-top">
      <img src="${cfg.client_logo_url}" alt="${cfg.client_name}">
      <div style="text-align:right;">
        <div class="eyebrow mono">Relatório mensal</div>
        <div class="period">${periodLabel}</div>
      </div>
    </div>
    <h1 class="serif">${cfg.client_name}</h1>
    <div class="period">Panorama de performance e disponibilidade &mdash; ${monthLabelCap}</div>
  </div>

  <div class="content">

    <p class="pullquote">${summaryHtml}</p>

    <div class="kpi-grid">
      <div class="kpi">
        <div class="icon">${icon('uptime')}</div>
        <div class="label">Disponibilidade</div>
        <div class="value">${fmtPct(uptime)}</div>
        <div class="status ${uptimeOk ? 'ok' : 'warn'}">${uptimeOk ? 'Saudável' : 'Atenção'}</div>
      </div>
      <div class="kpi">
        <div class="icon">${icon('volume')}</div>
        <div class="label">Solicitações</div>
        <div class="value">${fmtInt(totalRequests)}</div>
        <div class="status" style="color:var(--muted);">no mês</div>
      </div>
      <div class="kpi">
        <div class="icon">${icon('errors')}</div>
        <div class="label">Taxa de erros</div>
        <div class="value">${fmtPct(errorRate)}</div>
        <div class="status ${errorsOk ? 'ok' : 'warn'}">${errorsOk ? 'Saudável' : 'Atenção'}</div>
      </div>
      <div class="kpi">
        <div class="icon">${icon('speed')}</div>
        <div class="label">Resposta</div>
        <div class="value">${fmtMs(p95)}</div>
        <div class="status" style="color:var(--muted);">tempo médio</div>
      </div>
    </div>

    <div class="section-title serif">O que os usuários mais acessaram</div>
    <div class="section-sub">Recursos com mais uso real da plataforma no período &mdash; painéis internos de monitoramento não entram nessa conta.</div>
    ${barRows}

    <div class="divider"></div>

    <div class="section-title serif">O que cada número significa</div>
    <div class="section-sub" style="margin-bottom:0;"></div>
    <table style="width:100%;border-collapse:collapse;font-size:12.5px;color:var(--muted);margin-top:12px;">
      <tr><td style="padding:6px 0;width:140px;font-weight:600;color:var(--ink);vertical-align:top;">Disponibilidade</td><td style="padding:6px 0;">Quanto tempo a plataforma ficou no ar e respondendo. 100% é o ideal &mdash; qualquer queda vem de uma instabilidade real, não de manutenção programada.</td></tr>
      <tr><td style="padding:6px 0;font-weight:600;color:var(--ink);vertical-align:top;">Solicitações</td><td style="padding:6px 0;">Total de vezes que alguém (pessoa ou sistema) acessou a plataforma no mês &mdash; o termômetro mais direto de uso.</td></tr>
      <tr><td style="padding:6px 0;font-weight:600;color:var(--ink);vertical-align:top;">Taxa de erros</td><td style="padding:6px 0;">De cada 100 acessos, quantos travaram por falha técnica. Perto de zero é o esperado; acima disso, algo precisa de atenção.</td></tr>
      <tr><td style="padding:6px 0;font-weight:600;color:var(--ink);vertical-align:top;">Tempo de resposta</td><td style="padding:6px 0;">Quanto tempo a plataforma demora pra responder, em média. Poucos milissegundos é rápido o bastante pra passar despercebido.</td></tr>
    </table>

  </div>

  <div class="footer">
    <span>Linhas de log de erro no período: <strong style="color:var(--ink);">${fmtInt(errorLogLines)}</strong></span>
    <span class="brand mono">Arcus Cloud Security</span>
  </div>

</div>
</body>
</html>`;

return [{
  json: {
    subject: `Relatório mensal — ${cfg.client_name} — ${monthLabelCap}`,
    html,
    to: cfg.client_email_to,
    month_label: monthLabelCap,
  }
}];

// O node HTTP Request de multipart do n8n usa o nome do CAMPO binário como
// nome de arquivo no multipart -- Gotenberg exige que o arquivo principal se
// chame exatamente "index.html". Preparamos o binário aqui com esse nome
// antes de chamar o Gotenberg.
const item = $input.first();
const buffer = Buffer.from(item.json.html, 'utf-8');
return [{
  json: item.json,
  binary: {
    report_html: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
    },
  },
}];
